  for(String invalid:new String[]{"{\"schema\":1,\"total\":0,\"checked\":0}",new org.json.JSONObject(encoded).put("intervalMinutes",-1).toString(),new org.json.JSONObject(encoded).put("intervalMinutes",10081).toString()}){boolean rejected=false;try{ChaoxingCache.decode(invalid);}catch(org.json.JSONException e){rejected=true;}check(rejected,"Malformed task cache accepted");}
